  "translation": "关关鸣叫的雎鸠，相伴在河中小洲。美丽贤淑的女子，真是君子的好配偶。长短不齐的荇菜，左右捞取。美丽贤淑的女子，日日夜夜都想追求她。追求不到，日夜思念。思念悠悠，翻来覆去难入睡。长短不齐的荇菜，左右采摘。美丽贤淑的女子，弹琴鼓瑟亲近她。长短不齐的荇菜，左右拔取。美丽贤淑的女子，敲钟击鼓让她快乐。",
